insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('5ba18c12-bae3-51ef-8d97-bfcaacd53237', 'Squat con bilanciere', array['quadriceps', 'glutes']::text[], array['hamstrings', 'core']::text[], 'barbell', 'intermediate', array['Posiziona il bilanciere sui trapezi, piedi alla larghezza delle spalle e punte leggermente extraruotate.', 'Inspira, attiva il core e scendi spingendo le anche indietro con le ginocchia in linea con le punte.', 'Raggiungi almeno il parallelo mantenendo la schiena neutra e i talloni a terra.', 'Risali spingendo con tutto il piede ed espira nella parte finale del movimento.']::text[], array['/exercises/squat-bilanciere-0.jpg', '/exercises/squat-bilanciere-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('3f643115-29c5-50cd-a085-536c762402b4', 'Hip Thrust', array['glutes']::text[], array['hamstrings', 'core']::text[], 'barbell', 'intermediate', array['Appoggia la parte alta della schiena su una panca e posiziona il bilanciere imbottito sulle anche.', 'Piedi a terra alla larghezza delle anche, tibie verticali nella posizione alta.', 'Spingi con i talloni ed estendi le anche fino ad allineare spalle, anche e ginocchia.', 'Contrai i glutei per un secondo in alto e scendi in modo controllato.']::text[], array['/exercises/hip-thrust-0.jpg', '/exercises/hip-thrust-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('48c63c33-d1b6-59ca-a80f-a997717f4c6e', 'Leg Press', array['quadriceps', 'glutes']::text[], array['hamstrings', 'calves']::text[], 'machine', 'beginner', array['Siediti con schiena e bacino aderenti allo schienale, piedi sulla pedana alla larghezza delle spalle.', 'Sblocca i fermi e scendi piegando le ginocchia verso il petto senza sollevare il bacino.', 'Spingi la pedana fino quasi alla completa estensione, senza bloccare le ginocchia.']::text[], array['/exercises/leg-press-0.jpg', '/exercises/leg-press-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('782e2115-f45f-5b98-9685-0a981af47015', 'Affondi con manubri', array['quadriceps', 'glutes']::text[], array['hamstrings', 'core']::text[], 'dumbbell', 'intermediate', array['In piedi con un manubrio per mano, braccia distese lungo i fianchi.', 'Fai un passo in avanti e scendi finché entrambe le ginocchia formano circa 90°.', 'Mantieni il busto eretto e il ginocchio anteriore in linea con il piede.', 'Spingi sul tallone anteriore per tornare in posizione e alterna le gambe.']::text[], array['/exercises/affondi-manubri-0.jpg', '/exercises/affondi-manubri-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('8039c28f-9904-5c6b-961d-63dacf202d3e', 'Stacco rumeno', array['hamstrings', 'glutes']::text[], array['back', 'core']::text[], 'barbell', 'intermediate', array['In piedi con il bilanciere in presa prona e le ginocchia leggermente flesse.', 'Spingi le anche indietro facendo scorrere il bilanciere lungo le cosce, schiena neutra.', 'Scendi fino a sentire l''allungamento dei femorali, poco sotto le ginocchia.', 'Risali estendendo le anche e contraendo i glutei.']::text[], array['/exercises/stacco-rumeno-0.jpg', '/exercises/stacco-rumeno-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('60e27e08-ae8c-5aec-84ce-49c38aa0fd27', 'Stacco da terra', array['back', 'hamstrings', 'glutes']::text[], array['quadriceps', 'forearms', 'core']::text[], 'barbell', 'advanced', array['Piedi sotto il bilanciere alla larghezza delle anche, impugnatura appena fuori dalle gambe.', 'Abbassa le anche, petto in fuori, schiena neutra e spalle sopra il bilanciere.', 'Spingi il pavimento con le gambe mantenendo il bilanciere a contatto con le tibie.', 'Completa estendendo anche e ginocchia insieme, poi riporta a terra con controllo.']::text[], array['/exercises/stacco-da-terra-0.jpg', '/exercises/stacco-da-terra-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('18e0edbb-a0a5-5613-aa2f-9313126ab8bb', 'Goblet squat', array['quadriceps', 'glutes']::text[], array['core']::text[], 'kettlebell', 'beginner', array['Tieni un kettlebell o un manubrio vicino al petto con entrambe le mani.', 'Scendi tra le gambe con i gomiti all''interno delle ginocchia e il busto alto.', 'Risali spingendo con i talloni senza perdere la posizione della schiena.']::text[], array['/exercises/goblet-squat-0.jpg', '/exercises/goblet-squat-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('044c01c2-0de6-5f08-924f-b356dbe5ed9c', 'Leg curl sdraiato', array['hamstrings']::text[], array['calves']::text[], 'machine', 'beginner', array['Sdraiati prono sulla macchina con il rullo appena sopra i talloni.', 'Fletti le ginocchia portando i talloni verso i glutei senza sollevare il bacino.', 'Fai una breve pausa e torna giù lentamente.']::text[], array['/exercises/leg-curl-0.jpg', '/exercises/leg-curl-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('6a37cb87-003b-5613-ae25-16f94429eb6d', 'Leg extension', array['quadriceps']::text[], '{}'::text[], 'machine', 'beginner', array['Siediti con la schiena aderente e il rullo appoggiato sulla parte bassa delle tibie.', 'Estendi le ginocchia fino alla quasi completa estensione.', 'Mantieni un secondo la contrazione e scendi in modo controllato.']::text[], array['/exercises/leg-extension-0.jpg', '/exercises/leg-extension-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('79d2fe24-63c8-5561-aac4-8d7c70dea639', 'Glute bridge con bilanciere', array['glutes']::text[], array['hamstrings']::text[], 'barbell', 'beginner', array['Sdraiati a terra con le ginocchia piegate e il bilanciere sulle anche.', 'Spingi con i talloni e solleva il bacino fino ad allineare spalle, anche e ginocchia.', 'Contrai i glutei in alto e ritorna lentamente a terra.']::text[], array['/exercises/glute-bridge-0.jpg', '/exercises/glute-bridge-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('0dcbb457-d3ff-5383-b8eb-4b8fa6dfcc5b', 'Step-up con manubri', array['quadriceps', 'glutes']::text[], array['hamstrings', 'calves']::text[], 'dumbbell', 'beginner', array['In piedi davanti a una panca o a un box con un manubrio per mano.', 'Appoggia tutto il piede sul rialzo e sali spingendo con la gamba avanti.', 'Scendi con controllo e completa le ripetizioni prima di cambiare lato.']::text[], array['/exercises/step-up-0.jpg', '/exercises/step-up-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('2e57a259-acbb-57dc-98eb-04e99a07316c', 'Calf raise in piedi', array['calves']::text[], '{}'::text[], 'machine', 'beginner', array['Posiziona gli avampiedi sul rialzo con i talloni liberi e le spalle sotto i cuscinetti.', 'Sali sulle punte il più in alto possibile mantenendo le ginocchia distese.', 'Scendi lentamente fino a sentire l''allungamento dei polpacci.']::text[], array['/exercises/calf-raise-0.jpg', '/exercises/calf-raise-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('3154341a-679e-5541-90fe-00dc06348187', 'Stacco sumo', array['glutes', 'adductors', 'hamstrings']::text[], array['quadriceps', 'back']::text[], 'barbell', 'advanced', array['Piedi larghi con punte extraruotate, impugnatura stretta all''interno delle gambe.', 'Spingi le ginocchia verso l''esterno, petto alto e schiena neutra.', 'Solleva spingendo il pavimento con i piedi e chiudi estendendo le anche.']::text[], array['/exercises/stacco-sumo-0.jpg', '/exercises/stacco-sumo-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('badfba2a-0e9b-580a-9b4f-4c5b6f0b3e7b', 'Panca piana con bilanciere', array['chest']::text[], array['triceps', 'shoulders']::text[], 'barbell', 'intermediate', array['Sdraiati sulla panca con gli occhi sotto il bilanciere, scapole addotte e piedi ben piantati.', 'Impugna il bilanciere poco oltre la larghezza delle spalle e staccalo dai supporti.', 'Scendi controllato fino a sfiorare la parte bassa del petto.', 'Spingi verso l''alto mantenendo i polsi sopra i gomiti.']::text[], array['/exercises/panca-piana-0.jpg', '/exercises/panca-piana-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('19568d5b-c475-5796-9baa-a374468989b9', 'Panca inclinata con manubri', array['chest', 'shoulders']::text[], array['triceps']::text[], 'dumbbell', 'intermediate', array['Regola la panca a 30–45° e porta i manubri all''altezza del petto.', 'Spingi i manubri verso l''alto avvicinandoli senza farli toccare.', 'Scendi lentamente mantenendo i gomiti a circa 45° dal busto.']::text[], array['/exercises/panca-inclinata-manubri-0.jpg', '/exercises/panca-inclinata-manubri-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('ceae162c-a99b-5ab2-9e7a-a7bf394f3b21', 'Croci con manubri', array['chest']::text[], array['shoulders']::text[], 'dumbbell', 'beginner', array['Sdraiati su panca piana con i manubri sopra il petto e i gomiti leggermente flessi.', 'Apri le braccia ad arco fino a sentire l''allungamento del petto.', 'Richiudi lungo lo stesso arco contraendo i pettorali.']::text[], array['/exercises/croci-manubri-0.jpg', '/exercises/croci-manubri-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('ae43c934-ed4f-5195-baa2-cd87b9ae6526', 'Piegamenti sulle braccia', array['chest', 'triceps']::text[], array['shoulders', 'core']::text[], 'bodyweight', 'beginner', array['Mani poco oltre la larghezza delle spalle, corpo in linea dalla testa ai talloni.', 'Scendi fino a portare il petto vicino al pavimento con i gomiti a circa 45°.', 'Spingi per tornare su mantenendo il core attivo.']::text[], array['/exercises/piegamenti-0.jpg', '/exercises/piegamenti-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('1c3305c0-b4eb-5e0f-8f5e-d1faa7866a35', 'Croci ai cavi', array['chest']::text[], array['shoulders']::text[], 'cable', 'intermediate', array['Impugna le maniglie dei cavi alti e fai un passo avanti con il busto leggermente inclinato.', 'Porta le mani davanti al petto con un movimento ad arco, gomiti morbidi.', 'Ritorna lentamente fino a sentire l''allungamento dei pettorali.']::text[], array['/exercises/croci-cavi-0.jpg', '/exercises/croci-cavi-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('864c06a5-b33e-5e00-8aa7-b4bb3fd55c1e', 'Dip alle parallele', array['chest', 'triceps']::text[], array['shoulders']::text[], 'bodyweight', 'advanced', array['Sostieniti sulle parallele con le braccia distese e il busto leggermente inclinato in avanti.', 'Scendi piegando i gomiti fino a circa 90°.', 'Spingi per tornare in alto senza bloccare i gomiti.']::text[], array['/exercises/dip-parallele-0.jpg', '/exercises/dip-parallele-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('74491215-c972-5268-8f32-41adb209b1d0', 'Lat machine presa larga', array['back']::text[], array['biceps', 'shoulders']::text[], 'cable', 'beginner', array['Siediti con le cosce bloccate sotto i cuscinetti e impugna la barra con presa larga.', 'Tira la barra verso la parte alta del petto portando i gomiti verso i fianchi.', 'Ritorna in alto con controllo fino alla completa distensione delle braccia.']::text[], array['/exercises/lat-machine-0.jpg', '/exercises/lat-machine-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('ae5ab938-af44-5a42-b550-1a10744ef96a', 'Pulley basso', array['back']::text[], array['biceps', 'forearms']::text[], 'cable', 'beginner', array['Siediti con i piedi sulla pedana e le ginocchia leggermente flesse, busto eretto.', 'Tira la maniglia verso l''addome portando i gomiti indietro e stringendo le scapole.', 'Ritorna in avanti lentamente senza arrotondare la schiena.']::text[], array['/exercises/pulley-basso-0.jpg', '/exercises/pulley-basso-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('ebbeb3db-d5be-56e3-a39a-38ae9d9a4d96', 'Rematore con bilanciere', array['back']::text[], array['biceps', 'shoulders', 'core']::text[], 'barbell', 'intermediate', array['Busto inclinato a circa 45°, schiena neutra, bilanciere in presa prona.', 'Tira il bilanciere verso l''ombelico portando i gomiti indietro.', 'Abbassa con controllo mantenendo la posizione del busto.']::text[], array['/exercises/rematore-bilanciere-0.jpg', '/exercises/rematore-bilanciere-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('680f230c-3b0e-52a7-934a-8d6b804b2cc0', 'Rematore con manubrio', array['back']::text[], array['biceps', 'shoulders']::text[], 'dumbbell', 'beginner', array['Appoggia mano e ginocchio su una panca, schiena parallela al pavimento.', 'Tira il manubrio verso il fianco mantenendo il gomito vicino al corpo.', 'Scendi lentamente fino alla completa distensione e completa le ripetizioni per lato.']::text[], array['/exercises/rematore-manubrio-0.jpg', '/exercises/rematore-manubrio-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('66fa2613-d6c8-55ba-bd6d-a7210d5f4488', 'Trazioni alla sbarra', array['back']::text[], array['biceps', 'forearms', 'core']::text[], 'bodyweight', 'advanced', array['Appenditi alla sbarra con presa prona poco oltre la larghezza delle spalle.', 'Tira portando il petto verso la sbarra e i gomiti verso il basso.', 'Supera la sbarra con il mento e scendi lentamente fino a braccia distese.']::text[], array['/exercises/trazioni-0.jpg', '/exercises/trazioni-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('9d2c7deb-9930-58a3-9e7f-20845a63f5cc', 'Face pull', array['shoulders']::text[], array['back']::text[], 'cable', 'beginner', array['Imposta il cavo all''altezza del viso con la corda e impugnala con i pollici verso di te.', 'Tira la corda verso il viso aprendo le mani e portando i gomiti in alto e indietro.', 'Mantieni un secondo e ritorna con controllo.']::text[], array['/exercises/face-pull-0.jpg', '/exercises/face-pull-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('3d16aa2e-9aac-5f83-9e9b-d200b92147ad', 'Lento avanti con manubri', array['shoulders']::text[], array['triceps']::text[], 'dumbbell', 'intermediate', array['Seduto o in piedi, manubri all''altezza delle spalle con i palmi in avanti.', 'Spingi i manubri sopra la testa fino alla quasi completa estensione.', 'Scendi lentamente fino all''altezza delle orecchie.']::text[], array['/exercises/lento-manubri-0.jpg', '/exercises/lento-manubri-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('2a66a1dd-e626-52e6-8510-5f9a09506ca1', 'Alzate laterali', array['shoulders']::text[], '{}'::text[], 'dumbbell', 'beginner', array['In piedi con un manubrio per mano e i gomiti leggermente flessi.', 'Solleva le braccia lateralmente fino all''altezza delle spalle.', 'Scendi lentamente senza dondolare il busto.']::text[], array['/exercises/alzate-laterali-0.jpg', '/exercises/alzate-laterali-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('f54739d7-c574-5cc1-88f6-fa25f8c5df33', 'Arnold press', array['shoulders']::text[], array['triceps']::text[], 'dumbbell', 'intermediate', array['Seduto con i manubri davanti al viso e i palmi rivolti verso di te.', 'Spingi verso l''alto ruotando i palmi in avanti durante la salita.', 'Ritorna invertendo la rotazione fino alla posizione iniziale.']::text[], array['/exercises/arnold-press-0.jpg', '/exercises/arnold-press-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('6c7615c1-76da-54ca-972c-0bcf0d80eac4', 'Curl con manubri', array['biceps']::text[], array['forearms']::text[], 'dumbbell', 'beginner', array['In piedi, braccia distese e palmi rivolti in avanti.', 'Fletti i gomiti portando i manubri verso le spalle senza muovere i gomiti.', 'Scendi lentamente fino alla completa distensione.']::text[], array['/exercises/curl-manubri-0.jpg', '/exercises/curl-manubri-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('7360e628-150e-5e6a-8650-a7bb603ecff9', 'Curl a martello', array['biceps', 'forearms']::text[], '{}'::text[], 'dumbbell', 'beginner', array['Impugna i manubri con presa neutra, palmi rivolti verso il corpo.', 'Fletti i gomiti mantenendo la presa neutra per tutto il movimento.', 'Ritorna con controllo senza slanci.']::text[], array['/exercises/curl-martello-0.jpg', '/exercises/curl-martello-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('a0b892b4-9420-5782-a981-955f9d19f069', 'Push down ai cavi', array['triceps']::text[], '{}'::text[], 'cable', 'beginner', array['In piedi davanti al cavo alto, impugna la barra con i gomiti vicini ai fianchi.', 'Estendi i gomiti spingendo la barra verso il basso.', 'Ritorna fino a 90° mantenendo i gomiti fermi.']::text[], array['/exercises/pushdown-cavi-0.jpg', '/exercises/pushdown-cavi-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('5032b8c8-483b-5ce4-87a4-902c9fad5400', 'French press con bilanciere EZ', array['triceps']::text[], '{}'::text[], 'barbell', 'intermediate', array['Sdraiato su panca piana, bilanciere EZ sopra il petto a braccia tese.', 'Fletti i gomiti portando il bilanciere verso la fronte, gomiti fermi.', 'Estendi le braccia tornando alla posizione iniziale.']::text[], array['/exercises/french-press-0.jpg', '/exercises/french-press-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('4f0dc3ab-c4b5-5daa-a471-d05c6fc99e5d', 'Plank', array['core']::text[], array['shoulders', 'glutes']::text[], 'bodyweight', 'beginner', array['Appoggia avambracci e punte dei piedi a terra, gomiti sotto le spalle.', 'Mantieni il corpo in linea retta contraendo addome e glutei.', 'Respira regolarmente e mantieni la posizione per il tempo indicato.']::text[], array['/exercises/plank-0.jpg', '/exercises/plank-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('4ec6bc0f-3ca3-530a-a70f-adbc556aa2b9', 'Crunch', array['core']::text[], '{}'::text[], 'bodyweight', 'beginner', array['Sdraiati supino con le ginocchia piegate e le mani vicino alle tempie.', 'Solleva le spalle da terra avvicinando lo sterno al bacino.', 'Ritorna giù lentamente senza tirare la testa con le mani.']::text[], array['/exercises/crunch-0.jpg', '/exercises/crunch-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('c4e8d05e-6c91-5a27-bed8-117b56a1fb02', 'Russian twist', array['core']::text[], '{}'::text[], 'bodyweight', 'beginner', array['Seduto con le ginocchia piegate, busto inclinato indietro e piedi sollevati o a terra.', 'Ruota il busto da un lato all''altro portando le mani accanto al fianco.', 'Mantieni la schiena dritta e il movimento controllato.']::text[], array['/exercises/russian-twist-0.jpg', '/exercises/russian-twist-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('77afa854-1bfe-569d-abad-84ab87fcda62', 'Leg raise alla sbarra', array['core']::text[], array['forearms']::text[], 'bodyweight', 'advanced', array['Appenditi alla sbarra con le braccia distese.', 'Solleva le gambe tese o piegate fino all''altezza delle anche o oltre.', 'Scendi lentamente evitando di oscillare.']::text[], array['/exercises/leg-raise-sbarra-0.jpg', '/exercises/leg-raise-sbarra-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('84a8621a-0cde-5690-aa22-60416254a4cb', 'Mountain climber', array['core', 'cardio']::text[], array['shoulders', 'quadriceps']::text[], 'bodyweight', 'beginner', array['Parti dalla posizione di plank a braccia tese.', 'Porta alternativamente le ginocchia verso il petto con ritmo sostenuto.', 'Mantieni il bacino stabile e le spalle sopra i polsi.']::text[], array['/exercises/mountain-climber-0.jpg', '/exercises/mountain-climber-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('8c4dc162-b081-5a50-bc11-aaa2c0ddf190', 'Kettlebell swing', array['glutes', 'hamstrings']::text[], array['back', 'core', 'shoulders']::text[], 'kettlebell', 'intermediate', array['Piedi alla larghezza delle spalle, kettlebell a terra davanti a te.', 'Porta il kettlebell indietro tra le gambe spingendo le anche indietro.', 'Estendi le anche con forza e lascia salire il kettlebell all''altezza del petto.', 'Accompagna la discesa e ripeti in modo fluido.']::text[], array['/exercises/kettlebell-swing-0.jpg', '/exercises/kettlebell-swing-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('9e034036-bf71-5201-bd45-4a609c373857', 'Vogatore', array['cardio', 'back']::text[], array['quadriceps', 'biceps']::text[], 'machine', 'beginner', array['Siediti, blocca i piedi e impugna la maniglia a braccia tese.', 'Spingi con le gambe, poi inclina leggermente il busto e tira la maniglia verso l''addome.', 'Ritorna invertendo la sequenza: braccia, busto, gambe.']::text[], array['/exercises/vogatore-0.jpg', '/exercises/vogatore-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('ad7e56d3-dd96-5a5d-b63e-d92fc6d6b5a1', 'Corsa su tapis roulant', array['cardio']::text[], array['quadriceps', 'calves']::text[], 'machine', 'beginner', array['Imposta velocità e pendenza secondo l''intensità indicata.', 'Mantieni una postura eretta e una falcata naturale.', 'Monitora la frequenza cardiaca e defatica negli ultimi minuti.']::text[], array['/exercises/tapis-roulant-0.jpg', '/exercises/tapis-roulant-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('17e9093f-f04e-56f9-ada5-a3eb8a025c2d', 'Cyclette', array['cardio']::text[], array['quadriceps', 'hamstrings']::text[], 'machine', 'beginner', array['Regola la sella all''altezza dell''anca, con il ginocchio leggermente flesso in basso.', 'Pedala a ritmo costante con la resistenza indicata.', 'Varia la resistenza seguendo gli intervalli del programma.']::text[], array['/exercises/cyclette-0.jpg', '/exercises/cyclette-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('1cbd61cd-8af9-5db5-b27b-49bb643f65c3', 'Salto della corda', array['cardio', 'calves']::text[], array['shoulders']::text[], 'other', 'beginner', array['Impugna la corda con i gomiti vicini ai fianchi.', 'Ruota la corda con i polsi e salta sugli avampiedi con piccoli rimbalzi.', 'Mantieni un ritmo regolare per il tempo indicato.']::text[], array['/exercises/salto-corda-0.jpg', '/exercises/salto-corda-1.jpg']::text[], false) on conflict (id) do nothing;
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, difficulty, instructions, image_urls, is_custom) values ('0b69b574-79a6-5da1-bb2c-33f849e37b2d', 'Jump squat', array['quadriceps', 'glutes']::text[], array['calves', 'cardio']::text[], 'bodyweight', 'intermediate', array['Parti in posizione di squat con le braccia davanti.', 'Salta esplosivamente verso l''alto estendendo anche e ginocchia.', 'Atterra morbido sugli avampiedi e torna subito in squat.']::text[], array['/exercises/jump-squat-0.jpg', '/exercises/jump-squat-1.jpg']::text[], false) on conflict (id) do nothing;
